$\begin{align}
&\phantom{=}h'(x)
\\\\
&=\dfrac{d}{dx}\left(\sqrt{x}\ln(x)\right)
\\\\
&=\dfrac{d}{dx}\left(\sqrt{x}\right)\ln(x)+\sqrt{x}\dfrac{d}{dx}(\ln(x))&&\gray{\text{The product rule}}
\\\\
&=\dfrac{d}{dx}\left(x^{^{\Large\frac{1}{2}}}\right)\ln(x)+\sqrt{x}\dfrac{d}{dx}(\ln(x))&&\gray{\text{Write }\sqrt{x} \text{ as a power}}
\\\\
&=\dfrac12x^{^{\Large-\frac{1}{2}}}\cdot \ln(x)+\sqrt{x} \cdot \dfrac1x&&\gray{\text{Differentiate }x^{^{\Large\frac{1}{2}}}\text{ and }\ln(x)}
\\\\
&=\dfrac{\ln(x)}{2\sqrt{x}}+\dfrac{\sqrt{x}}{x}&&\gray{\text{Simplify}}
\\\\
&=\dfrac{\ln(x)}{2\sqrt{x}}+\dfrac{1}{\sqrt{x}}&&\gray{\text{Simplify}}
\end{align}$
